const setAgentThreadTitle = `-- name: SetAgentThreadTitle :execrows
UPDATE agent_threads
SET title = $3, updated_at = now()
WHERE workspace_id = $1 AND id = $2 AND title = '' AND deleted_at IS NULL
`

type SetAgentThreadTitleParams struct {
	WorkspaceID uuid.UUID `json:"workspace_id"`
	ID          uuid.UUID `json:"id"`
	Title       string    `json:"title"`
}

// Generated titles never overwrite a user's rename: the WHERE clause requires
// the title to still be empty, so a rename that landed while the fast model
// was thinking wins.
func (q *Queries) SetAgentThreadTitle(ctx context.Context, arg SetAgentThreadTitleParams) (int64, error) {
	result, err := q.db.Exec(ctx, setAgentThreadTitle, arg.WorkspaceID, arg.ID, arg.Title)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const softDeleteAgentThread = `-- name: SoftDeleteAgentThread :execrows
UPDATE agent_threads
SET deleted_at = now(), updated_at = now(), active_run_id = NULL
WHERE workspace_id = $1 AND created_by_user_id = $2 AND id = $3 AND deleted_at IS NULL
`

type SoftDeleteAgentThreadParams struct {
	WorkspaceID     uuid.UUID `json:"workspace_id"`
	CreatedByUserID uuid.UUID `json:"created_by_user_id"`
	ID              uuid.UUID `json:"id"`
}

// Soft delete: the transcript stays for audit while disappearing from every
// read path (all of which filter deleted_at IS NULL).
func (q *Queries) SoftDeleteAgentThread(ctx context.Context, arg SoftDeleteAgentThreadParams) (int64, error) {
	result, err := q.db.Exec(ctx, softDeleteAgentThread, arg.WorkspaceID, arg.CreatedByUserID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
